import{_ as t,o,c as n,a5 as i}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"UC 01 — Authentication & User/Client Profile (UC-001 – UC-013)","description":"","frontmatter":{},"headers":[],"relativePath":"ba/use-cases/01-authentication-profile.md","filePath":"ba/use-cases/01-authentication-profile.md"}'),c={name:"ba/use-cases/01-authentication-profile.md"};function d(l,e,a,r,h,s){return o(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="uc-01-—-authentication-user-client-profile-uc-001-–-uc-013" tabindex="-1">UC 01 — Authentication &amp; User/Client Profile (<code>UC-001</code> – <code>UC-013</code>) <a class="header-anchor" href="#uc-01-—-authentication-user-client-profile-uc-001-–-uc-013" aria-label="Permalink to &quot;UC 01 — Authentication &amp; User/Client Profile (`UC-001` – `UC-013`)&quot;">​</a></h1><p>&gt; <a href="./README.html">← UC Master Index</a> | <a href="./../02-authentication-profile.html">Domain BA Spec: 02-authentication-profile.md</a> | <a href="./02-agency-workspace.html">02-agency-workspace.md &gt;&gt;</a> &gt; &gt; Đồng bộ chuẩn xác 1-đối-1 với <code>Các FR của hệ thống - Feature_Function Requirement.csv</code> và <code>AGENTS.md</code>. Chỉ sử dụng <strong>6 Vai trò Hệ thống Chuẩn (<code>Guest</code>, <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code>)</strong>.</p><hr><h2 id="_1-bang-tong-hop-use-cases-13-ucs" tabindex="-1">1. Bảng Tổng Hợp Use Cases (13 UCs) <a class="header-anchor" href="#_1-bang-tong-hop-use-cases-13-ucs" aria-label="Permalink to &quot;1. Bảng Tổng Hợp Use Cases (13 UCs)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">UC ID</th><th style="text-align:left;">Use Case Title</th><th style="text-align:left;">Canonical Actor(s)</th><th style="text-align:center;">Related FR</th><th style="text-align:left;">Business Rules</th></tr></thead><tbody><tr><td style="text-align:center;"><code>UC-001</code></td><td style="text-align:left;">Sign Up</td><td style="text-align:left;"><code>Guest</code></td><td style="text-align:center;"><code>3.2.1</code></td><td style="text-align:left;"><code>BR-01, BR-02, BR-03, BR-04</code></td></tr><tr><td style="text-align:center;"><code>UC-002</code></td><td style="text-align:left;">Sign In with Email</td><td style="text-align:left;"><code>Guest</code>, <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code></td><td style="text-align:center;"><code>3.2.2</code></td><td style="text-align:left;"><code>BR-01, BR-02, BR-05, BR-06, BR-09</code></td></tr><tr><td style="text-align:center;"><code>UC-003</code></td><td style="text-align:left;">Sign In with Google OAuth</td><td style="text-align:left;"><code>Guest</code>, <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code></td><td style="text-align:center;"><code>3.2.3</code></td><td style="text-align:left;"><code>BR-01, BR-05, BR-07</code></td></tr><tr><td style="text-align:center;"><code>UC-004</code></td><td style="text-align:left;">Reset Password</td><td style="text-align:left;"><code>Guest</code>, <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code></td><td style="text-align:center;"><code>3.2.4</code></td><td style="text-align:left;"><code>BR-01, BR-02, BR-03, BR-04, BR-08</code></td></tr><tr><td style="text-align:center;"><code>UC-005</code></td><td style="text-align:left;">Change Password</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code></td><td style="text-align:center;"><code>3.2.5</code></td><td style="text-align:left;"><code>BR-02, BR-08</code></td></tr><tr><td style="text-align:center;"><code>UC-006</code></td><td style="text-align:left;">OTP Verification</td><td style="text-align:left;"><code>Guest</code>, <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code></td><td style="text-align:center;"><code>3.2.6</code></td><td style="text-align:left;"><code>BR-03, BR-04, BR-05</code></td></tr><tr><td style="text-align:center;"><code>UC-007</code></td><td style="text-align:left;">Two-Factor Authentication (2FA, TOTP)</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code></td><td style="text-align:center;"><code>3.2.7</code></td><td style="text-align:left;"><code>BR-05, BR-09</code></td></tr><tr><td style="text-align:center;"><code>UC-008</code></td><td style="text-align:left;">Logout</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code></td><td style="text-align:center;"><code>3.2.8</code></td><td style="text-align:left;"><code>BR-05</code></td></tr><tr><td style="text-align:center;"><code>UC-009</code></td><td style="text-align:left;">Delete Account</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code></td><td style="text-align:center;"><code>3.2.9</code></td><td style="text-align:left;"><code>BR-10, BR-16</code></td></tr><tr><td style="text-align:center;"><code>UC-010</code></td><td style="text-align:left;">View User Profile</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code></td><td style="text-align:center;"><code>3.3.1</code></td><td style="text-align:left;"><code>BR-05, BR-11</code></td></tr><tr><td style="text-align:center;"><code>UC-011</code></td><td style="text-align:left;">Update User Profile</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code></td><td style="text-align:center;"><code>3.3.2</code></td><td style="text-align:left;"><code>BR-11, BR-12</code></td></tr><tr><td style="text-align:center;"><code>UC-012</code></td><td style="text-align:left;">View Client Profile</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Client</code></td><td style="text-align:center;"><code>3.3.3</code></td><td style="text-align:left;"><code>BR-13, BR-14</code></td></tr><tr><td style="text-align:center;"><code>UC-013</code></td><td style="text-align:left;">Update Client Profile</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Client</code></td><td style="text-align:center;"><code>3.3.4</code></td><td style="text-align:left;"><code>BR-12, BR-13, BR-14</code></td></tr></tbody></table><hr><h2 id="uc-001-—-sign-up" tabindex="-1">UC-001 — Sign Up <a class="header-anchor" href="#uc-001-—-sign-up" aria-label="Permalink to &quot;UC-001 — Sign Up&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.2.1</code> (3.2 Authentication &amp; Authorization)</li><li><strong>Canonical Actor(s):</strong> <code>Guest</code></li><li><strong>Business Rules:</strong> <code>BR-01, BR-02, BR-03, BR-04</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG04, MSG05, MSG06, MSG08, MSG10</code></li><li><strong>Specification &amp; Flow:</strong> Đăng ký tài khoản mới bằng Họ tên, Email và Mật khẩu trên màn hình Register (/register). Hệ thống chuẩn hóa email về chữ thường (lowercase) để kiểm tra trùng lặp không phân biệt hoa/thường (BR-01), kiểm tra độ mạnh mật khẩu (tối thiểu 8 ký tự và có ít nhất 1 chữ số) và băm mật khẩu một chiều bằng bcrypt (BR-02). Tài khoản mới khởi tạo ở trạng thái PENDING_VERIFICATION, hệ thống sinh mã OTP 6 chữ số có hiệu lực 10 phút (BR-03) gửi qua email và chuyển hướng sang màn hình xác thực OTP (3.2.6).</li></ul><hr><h2 id="uc-002-—-sign-in-with-email" tabindex="-1">UC-002 — Sign In with Email <a class="header-anchor" href="#uc-002-—-sign-in-with-email" aria-label="Permalink to &quot;UC-002 — Sign In with Email&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.2.2</code> (3.2 Authentication &amp; Authorization)</li><li><strong>Canonical Actor(s):</strong> <code>Guest</code>, <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code></li><li><strong>Business Rules:</strong> <code>BR-01, BR-02, BR-05, BR-06, BR-09</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG04, MSG08, MSG09, MSG11, MSG12</code></li><li><strong>Specification &amp; Flow:</strong> Đăng nhập trực tiếp bằng Email và Mật khẩu trên màn hình Sign In (/login) mà không cần gửi lại OTP mỗi lần đăng nhập (trừ trường hợp tài khoản bật 2FA TOTP ở 3.2.7). Hệ thống chuẩn hóa email về chữ thường, đối chiếu mật khẩu băm (BR-02), kiểm tra trạng thái tài khoản đã xác thực email và không bị khóa/vô hiệu hóa (BR-05). Nếu hợp lệ, cấp cặp JWT Access Token (15 phút) và Refresh Token (30 ngày) để khởi tạo phiên làm việc.</li></ul><hr><h2 id="uc-003-—-sign-in-with-google-oauth" tabindex="-1">UC-003 — Sign In with Google OAuth <a class="header-anchor" href="#uc-003-—-sign-in-with-google-oauth" aria-label="Permalink to &quot;UC-003 — Sign In with Google OAuth&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.2.3</code> (3.2 Authentication &amp; Authorization)</li><li><strong>Canonical Actor(s):</strong> <code>Guest</code>, <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code></li><li><strong>Business Rules:</strong> <code>BR-01, BR-05, BR-07</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG03, MSG08, MSG12, MSG13</code></li><li><strong>Specification &amp; Flow:</strong> Đăng nhập hoặc đăng ký nhanh một chạm thông qua Google OAuth 2.0 (/login, /register). Hệ thống xác thực Google ID Token và cờ email_verified với máy chủ Google, chuẩn hóa email về chữ thường (BR-01). Nếu email đã tồn tại thì tự động liên kết/đăng nhập vào tài khoản hiện có; nếu chưa tồn tại thì tự động khởi tạo tài khoản ở trạng thái ACTIVE (lấy tên và ảnh đại diện từ Google), kiểm tra trạng thái không bị khóa (BR-05) và cấp JWT phiên làm việc.</li></ul><hr><h2 id="uc-004-—-reset-password" tabindex="-1">UC-004 — Reset Password <a class="header-anchor" href="#uc-004-—-reset-password" aria-label="Permalink to &quot;UC-004 — Reset Password&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.2.4</code> (3.2 Authentication &amp; Authorization)</li><li><strong>Canonical Actor(s):</strong> <code>Guest</code>, <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code></li><li><strong>Business Rules:</strong> <code>BR-01, BR-02, BR-03, BR-04, BR-08</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG04, MSG05, MSG06, MSG07, MSG08, MSG14, MSG15, MSG17</code></li><li><strong>Specification &amp; Flow:</strong> Khôi phục mật khẩu khi quên trên màn hình Forgot Password (/forgot-password, /reset-password). Người dùng nhập email đã đăng ký để nhận mã xác thực OTP 6 chữ số hoặc liên kết đặt lại mật khẩu có thời hạn 10 phút (BR-03, tối đa 5 lần nhập sai BR-04). Sau khi xác nhận mã hợp lệ và nhập mật khẩu mới kèm xác nhận mật khẩu thỏa chính sách bảo mật (BR-02), hệ thống cập nhật mật khẩu băm mới và thu hồi toàn bộ các phiên đăng nhập cũ (BR-08).</li></ul><hr><h2 id="uc-005-—-change-password" tabindex="-1">UC-005 — Change Password <a class="header-anchor" href="#uc-005-—-change-password" aria-label="Permalink to &quot;UC-005 — Change Password&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.2.5</code> (3.2 Authentication &amp; Authorization)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code></li><li><strong>Business Rules:</strong> <code>BR-02, BR-08</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG05, MSG06, MSG07, MSG17, MSG18</code></li><li><strong>Specification &amp; Flow:</strong> Đổi mật khẩu chủ động khi đang đăng nhập tại phần Security Settings (/profile/security). Người dùng bắt buộc nhập Mật khẩu hiện tại, Mật khẩu mới (thỏa chuẩn bảo mật BR-02 và phải khác mật khẩu hiện tại BR-08) và Nhập lại mật khẩu xác nhận trùng khớp. Sau khi cập nhật mật khẩu băm mới, hệ thống thu hồi các Refresh Token của các thiết bị khác để bảo vệ tài khoản.</li></ul><hr><h2 id="uc-006-—-otp-verification" tabindex="-1">UC-006 — OTP Verification <a class="header-anchor" href="#uc-006-—-otp-verification" aria-label="Permalink to &quot;UC-006 — OTP Verification&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.2.6</code> (3.2 Authentication &amp; Authorization)</li><li><strong>Canonical Actor(s):</strong> <code>Guest</code>, <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code></li><li><strong>Business Rules:</strong> <code>BR-03, BR-04, BR-05</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG15, MSG16</code></li><li><strong>Specification &amp; Flow:</strong> Xác thực mã OTP 6 chữ số gửi qua email trên màn hình Verify OTP (/verify-otp) để kích hoạt tài khoản mới đăng ký (3.2.1) hoặc xác nhận khôi phục mật khẩu (3.2.4). Mã OTP chỉ sử dụng một lần trong thời hạn 10 phút (BR-03). Nếu nhập sai quá 5 lần liên tiếp, hệ thống khóa mã OTP hiện tại và bắt buộc nhấn Resend OTP (có thời gian chờ cooldown 60 giây) để nhận mã mới (BR-04).</li></ul><hr><h2 id="uc-007-—-two-factor-authentication-2fa-totp" tabindex="-1">UC-007 — Two-Factor Authentication (2FA, TOTP) <a class="header-anchor" href="#uc-007-—-two-factor-authentication-2fa-totp" aria-label="Permalink to &quot;UC-007 — Two-Factor Authentication (2FA, TOTP)&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.2.7</code> (3.2 Authentication &amp; Authorization)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code></li><li><strong>Business Rules:</strong> <code>BR-05, BR-09</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG07, MSG15, MSG19</code></li><li><strong>Specification &amp; Flow:</strong> Thiết lập và xác thực bảo mật 2 lớp (2FA TOTP chuẩn RFC 6238) bằng ứng dụng Authenticator (Google/Microsoft Authenticator). Hệ thống chỉ hiển thị mã QR để người dùng quét bằng ứng dụng Authenticator và ô nhập mã TOTP 6 chữ số (chu kỳ 30 giây, lệch tối đa ±1 bước) để kích hoạt hoặc xác nhận khi đăng nhập (BR-09); đã lược bỏ hoàn toàn phần hiển thị chuỗi Secret Key dạng văn bản copy và danh sách Backup Codes để tăng tính bảo mật và gọn giao diện.</li></ul><hr><h2 id="uc-008-—-logout" tabindex="-1">UC-008 — Logout <a class="header-anchor" href="#uc-008-—-logout" aria-label="Permalink to &quot;UC-008 — Logout&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.2.8</code> (3.2 Authentication &amp; Authorization)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code></li><li><strong>Business Rules:</strong> <code>BR-05</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG03, MSG07, MSG20</code></li><li><strong>Specification &amp; Flow:</strong> Đăng xuất khỏi phiên làm việc hiện tại từ thanh điều hướng chính. Hệ thống đưa JWT Access Token và Refresh Token hiện hành vào danh sách thu hồi trên Redis (Token Blacklist) để vô hiệu hóa phiên ngay lập tức, xóa thông tin xác thực nhạy cảm trên trình duyệt, nhưng giữ lại thông tin phương thức đăng nhập/nền tảng sử dụng gần nhất (last-used login hint &amp; workspace preference) để người dùng đăng nhập lại thuận tiện hơn (BR-05).</li></ul><hr><h2 id="uc-009-—-delete-account" tabindex="-1">UC-009 — Delete Account <a class="header-anchor" href="#uc-009-—-delete-account" aria-label="Permalink to &quot;UC-009 — Delete Account&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.2.9</code> (3.2 Authentication &amp; Authorization)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code></li><li><strong>Business Rules:</strong> <code>BR-10, BR-16</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG07, MSG18, MSG20, MSG36</code></li><li><strong>Specification &amp; Flow:</strong> Xóa tài khoản cá nhân theo cơ chế xóa mềm (Soft Delete) tại màn hình Account Settings (/profile/security). Người dùng bắt buộc nhập lại mật khẩu xác nhận và đồng ý hộp thoại cảnh báo. Hệ thống kiểm tra tài khoản không còn giữ quyền Owner duy nhất của Agency đang hoạt động hoặc còn giao dịch thanh toán treo (BR-10), chuyển trạng thái tài khoản sang DELETED (lưu vết thời gian xóa mềm 30 ngày) và thu hồi toàn bộ phiên đăng nhập (BR-16).</li></ul><hr><h2 id="uc-010-—-view-user-profile" tabindex="-1">UC-010 — View User Profile <a class="header-anchor" href="#uc-010-—-view-user-profile" aria-label="Permalink to &quot;UC-010 — View User Profile&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.3.1</code> (3.3 User &amp; Client Profile)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code></li><li><strong>Business Rules:</strong> <code>BR-05, BR-11</code></li><li><strong>System Messages:</strong> <code>MSG01, MSG02, MSG03, MSG07, MSG36</code></li><li><strong>Specification &amp; Flow:</strong> Xem thông tin hồ sơ cá nhân trên màn hình User Profile (/profile). Hiển thị đầy đủ các trường: Ảnh đại diện (Avatar), Họ và tên (Full Name), Địa chỉ Email (chỉ đọc), Số điện thoại, Chức danh/Vai trò hệ thống, Múi giờ, Ngôn ngữ giao diện (VI/EN), Ngày tham gia và trạng thái bảo mật 2FA.</li></ul><hr><h2 id="uc-011-—-update-user-profile" tabindex="-1">UC-011 — Update User Profile <a class="header-anchor" href="#uc-011-—-update-user-profile" aria-label="Permalink to &quot;UC-011 — Update User Profile&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.3.2</code> (3.3 User &amp; Client Profile)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code></li><li><strong>Business Rules:</strong> <code>BR-11, BR-12</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG03, MSG07, MSG21, MSG22</code></li><li><strong>Specification &amp; Flow:</strong> Cập nhật thông tin hồ sơ cá nhân và tải lên ảnh đại diện mới trên màn hình User Profile (/profile). Cho phép chỉnh sửa Họ tên, Số điện thoại, Giới thiệu ngắn, Ngôn ngữ/Múi giờ và tải ảnh Avatar (định dạng JPG, PNG, WEBP, dung lượng tối đa 5 MB lưu trữ trên S3); trường Email đăng nhập chính bị khóa cố định không cho phép thay đổi để bảo toàn định danh tài khoản (BR-11).</li></ul><hr><h2 id="uc-012-—-view-client-profile" tabindex="-1">UC-012 — View Client Profile <a class="header-anchor" href="#uc-012-—-view-client-profile" aria-label="Permalink to &quot;UC-012 — View Client Profile&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.3.3</code> (3.3 User &amp; Client Profile)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Client</code></li><li><strong>Business Rules:</strong> <code>BR-13, BR-14</code></li><li><strong>System Messages:</strong> <code>MSG01, MSG02, MSG03, MSG07, MSG36</code></li><li><strong>Specification &amp; Flow:</strong> Xem hồ sơ thương hiệu của Khách hàng (Client Profile) tại màn hình Client Profile (/client/profile). Mỗi tài khoản Client có một hồ sơ thương hiệu độc lập có thể tái sử dụng xuyên suốt nhiều Agency và Workspace khác nhau (gồm Tên công ty/thương hiệu, Logo, Lĩnh vực ngành nghề, Website, Mã số thuế, Địa chỉ, Thông tin liên hệ và Tông giọng thương hiệu) mà không cần phải nhập lại thông tin khi tham gia dự án mới (BR-13).</li></ul><hr><h2 id="uc-013-—-update-client-profile" tabindex="-1">UC-013 — Update Client Profile <a class="header-anchor" href="#uc-013-—-update-client-profile" aria-label="Permalink to &quot;UC-013 — Update Client Profile&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.3.4</code> (3.3 User &amp; Client Profile)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Client</code></li><li><strong>Business Rules:</strong> <code>BR-12, BR-13, BR-14</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG03, MSG07, MSG21, MSG22</code></li><li><strong>Specification &amp; Flow:</strong> Cập nhật hồ sơ thương hiệu (Client Profile) gồm Tên thương hiệu, Logo, Ngành hàng, Website, Địa chỉ, Số điện thoại liên hệ và mô tả nhận diện thương hiệu (/client/profile). Không cho phép thay đổi địa chỉ Email định danh của tài khoản Client (BR-14); mọi cập nhật sẽ tự động đồng bộ hiển thị tới các Workspace mà Client đang tham gia (BR-13).</li></ul>',44)])])}const m=t(c,[["render",d]]);export{u as __pageData,m as default};
